class Suggester:
    def __init__(self, dataset: Optional[List[Suggestion]] = None):
        self._dataset = dataset or list(DEFAULT_DATASET)

    def search(self, query: str, max_results: int = 8) -> dict:
        if not query or len(query.strip()) < 1:
            return {"query": query, "groups": [], "total": 0}

        q = query.strip().lower()
        results = []
        for item in self._dataset:
            score = self._compute_score(item, q)
            if score > 0:
                results.append((score, item))

        results.sort(key=lambda x: (-x[0], x[1].title.lower()))

        grouped = {}
        for score, item in results:
            group = item.category
            if group not in grouped:
                grouped[group] = []
            if len(grouped[group]) < max_results:
                grouped[group].append({
                    "id": item.id,
                    "title": item.title,
                    "description": item.description,
                    "category": item.category,
                    "url": item.url,
                    "score": score,
                })

        groups = [
            {"category": cat, "results": items}
            for cat, items in grouped.items()
        ]

        total = sum(len(g["results"]) for g in groups)
        return {"query": query, "groups": groups, "total": total}

    @staticmethod
    def _compute_score(item: Suggestion, query: str) -> float:
        title_lower = item.title.lower()
        desc_lower = item.description.lower()

        if title_lower == query:
            return 100.0
        if title_lower.startswith(query):
            return 80.0 + (len(query) / len(title_lower)) * 10
        if query in title_lower:
            return 60.0

        words = query.split()
        if all(w in title_lower for w in words):
            return 50.0

        if desc_lower.startswith(query):
            return 40.0
        if query in desc_lower:
            return 30.0

        if any(w in title_lower for w in words):
            return 20.0 + sum(w in title_lower for w in words)

        if any(w in desc_lower for w in words):
            return 10.0 + sum(w in desc_lower for w in words) * 0.5

        return 0.0

    def get_trending(self, limit: int = 5) -> list:
        trending_ids = ["p1", "g1", "l1", "f1", "pp1"]
        items = []
        for s in self._dataset:
            if s.id in trending_ids:
                items.append({
                    "id": s.id,
                    "title": s.title,
                    "category": s.category,
                    "url": s.url,
                })
        return items[:limit]

from flask import Flask, request, jsonify, send_file
from .cache import TTLCache
from .analytics import AnalyticsTracker
from .suggester import Suggester
from .widget import WIDGET_JS, DEMO_PAGE_HTML


def create_app():
    app = Flask(__name__)
    app.config["PROPAGATE_EXCEPTIONS"] = True

    cache = TTLCache(ttl=120, max_size=500)
    analytics = AnalyticsTracker()
    suggester = Suggester()

    @app.route("/")
    def index():
        return DEMO_PAGE_HTML

    @app.route("/widget/autocomplete.js")
    def widget_js():
        return WIDGET_JS, 200, {"Content-Type": "application/javascript"}

    @app.route("/api/suggest")
    def suggest():
        query = request.args.get("q", "").strip()
        if not query:
            return jsonify({"query": "", "groups": [], "total": 0})

        cache_key = f"suggest:{query.lower()}"
        cached = cache.get(cache_key)
        if cached is not None:
            return jsonify(cached)

        results = suggester.search(query, max_results=8)
        cache.set(cache_key, results)
        return jsonify(results)

    @app.route("/api/trending")
    def trending():
        cache_key = "trending"
        cached = cache.get(cache_key)
        if cached is not None:
            return jsonify(cached)

        results = suggester.get_trending()
        cache.set(cache_key, results, ttl=300)
        return jsonify(results)

    @app.route("/api/analytics", methods=["POST"])
    def analytics_event():
        data = request.get_json(silent=True) or {}
        event_type = data.get("type", "unknown")
        event_data = data.get("data", {})
        event = analytics.track(event_type, event_data)
        return jsonify({"success": True, "event": event}), 201

    @app.after_request
    def add_cors(response):
        response.headers["Access-Control-Allow-Origin"] = "*"
        response.headers["Access-Control-Allow-Headers"] = "Content-Type"
        response.headers["Access-Control-Allow-Methods"] = "GET, POST, OPTIONS"
        return response

    return app

