    track(this.apiBase, type, data);
  };

  function autoInit() {
    var inputs = document.querySelectorAll('input[data-autocomplete]');
    for (var i = 0; i < inputs.length; i++) {
      new AutocompleteSearch(inputs[i]);
    }
  }

